#define PI 3.14159265359
#define EPSILON 0.0001
#define S(a,b) smoothstep(a-EPSILON,a,b)

#ifdef GL_ES
precision mediump float;
#endif

uniform vec2 u_resolution;
uniform float u_time;
uniform vec2 u_mouse;
uniform vec2 u_offset;
uniform float u_zoom;

float rand(vec2 co){
  return fract(sin(dot(co.xy,vec2(12.9898,78.233))) * 43758.5453);
}

float smin(float a, float b, float k){
  float x = exp(-k * a);
  float y = exp(-k * b);
  return (a * x + b * y) / (x + y);
}

float smax(float a, float b, float k){
  return smin(a, b, -k);
}

mat2 rotate2d(float _angle){
    return mat2(cos(_angle),-sin(_angle),
                sin(_angle),cos(_angle));
}

float Checkboard(vec2 uv, float cell_count) {
	vec2 f_uv = fract(uv * cell_count);
	return step(.5, f_uv.x) * step(.5, f_uv.y) + step(-.5, -f_uv.x) * step(-.5, -f_uv.y);
}

float Grid(vec2 uv, float cell_count, float width) {
	vec2 size = width * 2. / u_resolution.xy;
	size *= 0.5 * u_zoom * cell_count;
	vec2 f_uv = fract(uv * cell_count);

	float grid = 0.;
	grid += smoothstep(1.- 1.5*size.y, 1.- 0.5*size.y, f_uv.y);
	grid += smoothstep(1.- 1.5*size.x, 1.- 0.5*size.x, f_uv.x);
	grid += smoothstep(f_uv.y-0.5*size.y, f_uv.y+0.5*size.y, size.y);
	grid += smoothstep(f_uv.x-0.5*size.x, f_uv.x+0.5*size.x, size.x);

	grid = min(grid, 1.);
	return grid;
}

float Point(vec2 uv, vec2 pos, float radius) {
	float size = radius / u_resolution.y;
	float p = distance(uv, pos);
	p = smoothstep(p-size*.1, p+size*.1, size);
	return p;
}

vec2 TransformedUV(vec2 uv) {
	uv -= .5;
	uv += u_offset / u_resolution.xy;
	uv *= u_zoom;
	return uv;
}

float Arrow(vec2 uv, vec2 mouse) {
	vec2 gv = fract(uv);
	vec2 id = floor(uv);

	vec2 center = vec2(.5,.5);

	vec2 dist = gv - center;

	float rad = atan(mouse.y - id.y - center.y, mouse.x - id.x - center.x);
	dist *= rotate2d(-rad);

	float arrow = S(abs(dist.x), .2) * S(abs(dist.y), .02);

	vec2 tri_gv = dist + center;
	tri_gv.x += .23;
	float tri = S(tri_gv.x*.5, tri_gv.y);
	tri *= S(tri_gv.y, 1.-tri_gv.x*.5);
	tri *= S(0.8, tri_gv.x);

	arrow = max(tri, arrow);

	vec2 m_id = id * .1;
	m_id.x -= sin(m_id.y) * 2.;
	m_id.y += rand(id) * .8;

	float mask = m_id.y + sin(m_id.x+m_id.y) + fract( (m_id.y*3.-m_id.x)*.01 );
	mask = fract(mask*.5);
	arrow *= S(0.7, mask);

	return arrow;
}

void main() {
	float c = 0.;
	vec2 uv = gl_FragCoord.xy / u_resolution.xy;	
	vec2 mouse = uv*u_mouse / gl_FragCoord.xy;

	uv = TransformedUV(uv);
	mouse = TransformedUV(mouse);

	c += Arrow(uv, mouse);
	c += Arrow(uv*2.13 + vec2(3.321, 45.54), mouse*2.13 + vec2(3.321, 45.54));
	c += Arrow(uv*.51 + vec2(.321, 46.654), mouse*.51 + vec2(.321, 46.654));
	c += Arrow(uv*.12 + vec2(111.321, 4.654), mouse*.12 + vec2(111.321, 4.654));

	//float mouse_point = Point(uv, mouse, 10.*u_zoom);
	//c += mouse_point;

	c = clamp(0., 1., c);
  vec3 col = vec3(c);

	vec3 color1 = vec3(.15, .15, .17);
	vec3 color2 = vec3(.88, .94, .94);

	col = mix(color1, color2, c);

  gl_FragColor = vec4(col,1.0); 
}

